macro_rules! Metrics {
    () => {
        # [doc = " A snapshot about resource usage."] # [derive (Debug , Clone , Copy , PartialEq , Eq , Default)] # [cfg_attr (feature = "serde" , derive (serde :: Serialize , serde :: Deserialize))] pub struct Metrics { # [doc = " The total amount of handles which can be used to access object information."] pub num_handles : usize , # [doc = " The amount of refreshes performed to reconcile with the ODB state on disk."] pub num_refreshes : usize , # [doc = " The amount of indices that are currently open and will be returned to handles."] pub open_reachable_indices : usize , # [doc = " The amount of reachable, known indices, which aren't opened yet."] pub known_reachable_indices : usize , # [doc = " The amount of packs which are open in memory and will be returned to handles."] pub open_reachable_packs : usize , # [doc = " The amount of packs that are reachable and will be returned to handles. They aren't open yet."] pub known_packs : usize , # [doc = " The amount of slots which are empty."] # [doc = ""] # [doc = " Over time these will fill, but they can be emptied as files are removed from disk."] pub unused_slots : usize , # [doc = " Unreachable indices are still using slots, but aren't returned to new handles anymore unless they still happen to"] # [doc = " know their id."] # [doc = ""] # [doc = " This allows to keep files available while they are still potentially required for operations like pack generation, despite"] # [doc = " the file on disk being removed or changed."] pub unreachable_indices : usize , # [doc = " Equivalent to `unreachable_indices`, but for mapped packed data files"] pub unreachable_packs : usize , # [doc = " The amount of loose object databases currently available for object retrieval."] # [doc = ""] # [doc = " There may be more than one if 'alternates' are used."] pub loose_dbs : usize , }
    };
}

Metrics!()